import {education,abilities,equivalents,levels} from './express-entry.js';
import {scoringSystems} from './systems.js';
const system=scoringSystems.get('canada-express-entry');let state=system.defaults();
const $=id=>document.getElementById(id),options=(items,value)=>items.map(([v,label])=>`<option value="${v}" ${String(v)===String(value)?'selected':''}>${label}</option>`).join('');
function select(key,label,items,hint='',wide=false){return `<label class="${wide?'wide':''}">${label}<select data-key="${key}" id="${key}">${options(items,state[key])}</select>${hint?`<span class="hint">${hint}</span>`:''}</label>`;}
function check(key,label,hint=''){return `<label class="check"><input type="checkbox" data-key="${key}" ${state[key]?'checked':''}><span>${label}${hint?`<small>${hint}</small>`:''}</span></label>`;}
const tri=(key,label,hint='')=>select(key,label,[['unknown','Not sure / not answered'],['yes','Yes'],['no','No']],hint,true);
const years=max=>Array.from({length:max+1},(_,i)=>[i,i===0?'None / less than 1 year':`${i}${i===max?'+':''} year${i===1?'':'s'}`]);
function language(key,title){const l=state[key],fr=key.toLowerCase().includes('french'),benchmark=fr?'NCLC':'CLB';return `<div class="language"><div class="language-head"><h3>${title}</h3><span class="tag">${benchmark}</span></div><label>Test results<select data-language="${key}" data-mode="tested">${options([['false','No valid test results'],['true','I have valid test results']],l.tested)}</select></label>${l.tested?`<div class="abilities">${abilities.map((ability,i)=>`<label>${ability}<select data-language="${key}" data-ability="${i}" aria-label="${title} ${ability} ${benchmark}">${options([[0,'Below 4'],...[4,5,6,7,8,9,10].map(x=>[x,`${benchmark} ${x===10?'10+':x}`])],l.levels[i])}</select></label>`).join('')}</div><div class="equivalents"><table><caption>Corresponding test scores</caption><thead><tr><th>Test</th>${abilities.map(a=>`<th>${a}</th>`).join('')}</tr></thead><tbody>${Object.entries(equivalents).filter(([name])=>fr?name.startsWith('TEF')||name.startsWith('TCF'):!name.startsWith('T')).map(([name,rows])=>`<tr><th scope="row">${name}</th>${l.levels.map((v,i)=>`<td>${v>=4?rows[v-4][i]:'Below '+rows[0][i].split('–')[0]}</td>`).join('')}</tr>`).join('')}</tbody></table></div>${fr?'<p class="hint">¹ TEF uses the “Équivalence ancien score” column, not the score out of 699.</p>':''}`:'<div class="empty">No language points claimed. Add valid results to explore this language.</div>'}</div>`;}
function form(){ $('basic-fields').innerHTML=`<label>Age<input data-key="age" id="age" type="number" min="0" max="100" step="1" required value="${state.age}"></label>${select('spouse','Spouse or common-law partner',[[false,'No / not accompanying / Canadian PR or citizen'],[true,'Accompanying, not Canadian PR or citizen']])}${select('education','Highest completed education',education.map((e,i)=>[i,e]),'For multiple credentials, at least one must be 3+ years. Professional degrees must be in an IRCC-eligible licensed field.',true)}<div class="wide">${check('educationValid','Canadian credential or valid immigration ECA','Foreign education requires an Educational Credential Assessment less than 5 years old. Clear this to exclude unassessed education points.')}</div>`;
 $('language-fields').innerHTML=language('english','English')+language('french','French')+'<p class="hint">Select only approved tests taken less than 2 years ago. CLB/NCLC 10+ is grouped because higher levels do not add CRS points. No IELTS Academic or One Skill Retake.</p>';
 $('remaining-fields').innerHTML=`<section id="experience"><div class="section-title"><span class="number">03</span><h2>Experience & additional points</h2></div><div class="fields">${select('canadian','Canadian skilled work',years(5),'Qualifying TEER 0–3 work in the last 10 years. Paid, authorized work while physically in Canada; exclude full-time student and self-employed work, unless an IRCC exception applies.')}${select('foreign','Foreign skilled work',years(3),'Qualifying paid TEER 0–3 experience outside Canada in the last 10 years.')}${select('canadianStudy','Eligible Canadian education',[[0,'None / does not meet requirements'],[15,'One- or two-year credential'],[30,'3+ years / master’s / professional / doctorate']],'Choose only qualifying study: generally at least 8 months full-time and physically in Canada. Language-majority programs and return-home scholarships are excluded; IRCC exceptions may apply.',true)}</div>${check('sibling','Qualifying sibling in Canada','Your or your accompanying spouse’s sibling, age 18+, living in Canada as a citizen or permanent resident.')}${check('nomination','Accepted Express Entry provincial nomination','A nomination linked to Express Entry adds 600 points. Additional points are capped at 600 in total.')}${check('certificate','Canadian certificate of qualification in a skilled trade','Issued by a provincial, territorial or federal authority; not an ordinary college trade diploma.')}</section>${state.spouse?`<section><div class="section-title"><span class="number">+</span><h2>Accompanying spouse</h2></div><div class="fields">${select('spouseEducation','Assessed / Canadian education',education.map((e,i)=>[i,e]),'Select none if a foreign credential has no valid ECA.')}${select('spouseCanadian','Qualifying Canadian work',years(5))}</div>${language('spouseEnglish','Spouse · English')}${language('spouseFrench','Spouse · French')}<p class="hint">Only the higher-scoring spouse language counts.</p></section>`:''}<section><div class="section-title"><span class="number">✓</span><h2>Program eligibility questions</h2></div><p>Work requirements have different time windows. Confirm each one independently.</p><div class="fields">${tri('outsideQuebec','Do you plan to settle outside Quebec?')}${tri('funds','Do you meet the current settlement-funds requirement?','Use IRCC’s current amount for your family size. A qualifying job offer plus authorization to work can provide an exemption for FSW/FST. CEC does not require settlement funds.')}</div>${check('authorized','Currently authorized to work in Canada')}<h3 class="subheading">Canadian Experience Class (CEC)</h3><div class="fields">${select('cecTeer','TEER category of qualifying Canadian work',[['01','TEER 0 or 1'],['23','TEER 2 or 3']],'Use the higher language threshold if relying on TEER 0/1 work.',true)}${tri('cecWork','At least 1 year of qualifying Canadian work in the last 3 years?','At least 1,560 hours over 12 months, maximum 30 hours/week counted; paid, authorized work in Canada, matching the NOC lead statement and most duties. Exclude full-time student and self-employed work (physician exceptions may apply).')}</div><h3 class="subheading">Federal Skilled Worker (FSW)</h3><div class="fields">${tri('fswWork','At least 1 continuous year in the same skilled occupation?','Paid TEER 0–3 work in your primary NOC within the last 10 years, matching its lead statement and most duties. At least 1,560 hours over 12 months; equivalent part-time work can count.')}${select('fswYears','Total qualifying skilled work in the last 10 years',years(6),'Canada and abroad combined, without double-counting overlapping work.',true)}</div>${check('fswOffer','Job offer meets IRCC’s FSW arranged-employment rules','At least one year, paid, full-time, non-seasonal TEER 0–3 work plus the applicable LMIA or work-permit exemption conditions. Review the official FSW source below; an ordinary offer alone is not enough.')}<details><summary>FSW adaptability factors (up to 10 points)</summary>${check('adaptWork','At least 1 year of authorized full-time skilled work in Canada')}${check('adaptStudy','At least 2 academic years of qualifying full-time study in Canada','Program at least 2 years, 15+ class hours/week, good academic standing.')}${check('relative','Qualifying adult relative in Canada','You or your accompanying spouse: parent, grandparent, child, grandchild, sibling, aunt/uncle, niece/nephew; age 18+, resident citizen or PR.')}${state.spouse?check('adaptSpouseStudy','Spouse: 2 academic years of qualifying Canadian study')+check('adaptSpouseWork','Spouse: 1 year of authorized full-time Canadian work'):''}<p class="hint">Spouse language CLB/NCLC 4+ and arranged employment are counted automatically when applicable.</p></details><h3 class="subheading">Federal Skilled Trades (FST)</h3><div class="fields">${tri('tradeWork','At least 2 years of qualifying trade work in the last 5 years?','3,120 paid hours over at least 2 years in the same eligible NOC: major groups 72 (not 726), 73, 82, 83, 92, 93 (not 932), minor group 6320 or unit 62200. Meet NOC duties and job requirements; qualified to practise where work was gained; student work excluded.')}${tri('tradeOffer','Qualifying full-time trade job offer for at least 1 year?','Must satisfy IRCC’s valid-offer rules, including applicable LMIA or exemption conditions. A Canadian trade certificate can satisfy this requirement instead.')}</div><p class="hint">All pathways remain subject to admissibility and document verification. Special public-policy exceptions require individual review.</p><button type="button" class="reset" id="reset">Reset profile</button></section>`;
}
function results(){const r=system.calculate(state),e=system.eligibility(state);$('total').textContent=r.total;$('total').setAttribute('aria-label',`${r.total} CRS points`);$('language-choice').textContent=r.hasLanguage?`${r.first} selected as your first official language. Best CRS combination applied.`:'No valid language test results selected.';
const row=(name,value)=>`<div class="break-row"><span>${name}</span><b>${value}</b></div>`,detail=obj=>Object.entries(obj).map(([k,v])=>`<div class="detail"><span>${k}</span><b>${v}</b></div>`).join('');
$('breakdown').innerHTML=row('Core / human capital',r.coreTotal)+row('Spouse factors',r.spouseTotal)+row('Skill transferability',r.transfer)+row('Additional points',r.additional)+`<details><summary>See point-by-point breakdown</summary>${detail(r.core)}<p>Spouse</p>${detail(r.spouseDetail)}<p>Transferability before caps</p>${detail(r.transferDetail)}<p>Education and foreign-work groups: 50 each. Combined transferability: 100.</p><p>Additional before 600 cap</p>${detail(r.additionalDetail)}<p>English first: ${r.alternatives.English} · French first: ${r.alternatives.French}. Ties use English.</p></details>`;
$('score-track').innerHTML=[r.coreTotal,r.spouseTotal,r.transfer,r.additional].map((v,i)=>`<span style="width:${v/12}%;background:${['#daef9a','#a8d9bb','#80b7a6','#e9dd9a'][i]}"></span>`).join('');
$('pathway-results').innerHTML=e.programs.map(p=>`<article class="pathway"><div class="pathway-head"><h3>${p.id} <span class="hint">/ ${p.name}</span></h3><span class="status ${p.status==='Likely eligible'?'pass':''}">${p.status}</span></div><ul>${p.checks.map(([name,ok])=>`<li>${ok===null?'?':ok?'✓':'×'} ${name}${ok===null?' — please confirm':''}</li>`).join('')}</ul>${p.id==='FSW'?`<details><summary>FSW selection points: ${e.fsw.total} / 100</summary>${Object.entries(e.fsw.detail).map(([k,v])=>`<div class="break-row"><span>${k}</span><b>${v}</b></div>`).join('')}</details>`:''}<a href="${p.url}" target="_blank" rel="noopener">Official ${p.id} requirements ↗</a></article>`).join('');}
function render(){form();results();}
$('profile-form').addEventListener('submit',e=>e.preventDefault());
$('profile-form').addEventListener('input',e=>{const t=e.target;if(t.dataset.key==='age'&&t.validity.valid&&t.value!==''){state.age=Number(t.value);results();}});
$('profile-form').addEventListener('change',e=>{const t=e.target,key=t.dataset.key,lang=t.dataset.language;if(lang){if(t.dataset.mode){state[lang].tested=t.value==='true';const scroll=window.scrollY;form();window.scrollTo(0,scroll);document.querySelector(`[data-language="${lang}"][data-mode]`).focus({preventScroll:true});}else{state[lang].levels[Number(t.dataset.ability)]=Number(t.value);const scroll=window.scrollY;form();window.scrollTo(0,scroll);document.querySelector(`[data-language="${lang}"][data-ability="${t.dataset.ability}"]`).focus({preventScroll:true});}}else if(key){if(key==='age'&&!t.validity.valid)return;state[key]=t.type==='checkbox'?t.checked:typeof state[key]==='boolean'?t.value==='true':typeof state[key]==='number'?Number(t.value):t.value;if(key==='spouse')form();}results();});
$('profile-form').addEventListener('click',e=>{if(e.target.id==='reset'){state=system.defaults();render();$('profile').scrollIntoView({behavior:'smooth'});}});
$('source-links').innerHTML=Object.entries(system.sources).map(([k,v])=>`<a href="${v}" target="_blank" rel="noopener">${k} ↗</a>`).join('')+'<span>Reviewed September 16, 2026</span>';
render();
if(document.modelContext?.registerTool){const lifecycle=new AbortController();Promise.resolve(document.modelContext.registerTool({name:'read_express_entry_estimate',description:'Read the current visible CRS estimate and pathway screening without changing the profile.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute(input){if(!input||typeof input!=='object'||Object.keys(input).length)throw new Error('Expected an empty object');return {score:system.calculate(state),eligibility:system.eligibility(state)};}},{signal:lifecycle.signal})).catch(()=>{});window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
